const resolveMidiInputs = (access, portId) => {
  if (!access || portId === MIDI_PORT_NONE) return [];
  if (portId === MIDI_PORT_ALL) return [...access.inputs.values()];
  const input = access.inputs.get(portId);
  return input ? [input] : [];
};

function createBaseElement(type, x, y, width, height, strokeColor = "#f8fafc") {
  return {
    id: `${type}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    type,
    x,
    y,
    width,
    height,
    angle: 0,
    strokeColor,
    backgroundColor: "transparent",
    fillStyle: "hachure",
    strokeWidth: 2,
    strokeStyle: "solid",
    roughness: 0,
    opacity: 100,
    groupIds: [],
    frameId: null,
    roundness: null,
    seed: Math.floor(Math.random() * 1000000),
    version: 1,
    versionNonce: Math.floor(Math.random() * 1000000),
    isDeleted: false,
    boundElements: null,
    updated: Date.now(),
    link: null,
    locked: false
  };
}

const getCanonicalExportBounds = elements => {
  const activeElements = (elements || []).filter(element => element && !element.isDeleted);
  if (!activeElements.length) return null;
  const [minX, minY, maxX, maxY] = getCommonBounds(activeElements);
  if (![minX, minY, maxX, maxY].every(Number.isFinite)) return null;
  return { minX, minY, maxX, maxY };
};

const getBakeExportPadding = elements => Math.max(2, ...(elements || []).map(element => {
  const strokeWidth = Number(element?.strokeWidth) || 1;
  const roughness = Number(element?.roughness) || 0;
  return Math.ceil(strokeWidth * (1 + roughness * 0.5));
}));

const isColorTransparent = (color) => {
  if (!color) return false;
  const c = color.trim().toLowerCase();
  if (c === "transparent") return true;
  if (c.startsWith("#") && c.length === 9 && c.endsWith("00")) return true;
  if (c.startsWith("#") && c.length === 5 && c.endsWith("0")) return true;
  if (c.startsWith("rgba")) {
    const parts = c.split(",");
    if (parts.length === 4) {
      const alpha = parseFloat(parts[3].replace(")", ""));
      return alpha === 0;
    }
  }
  return false;
};

const makeColorTransparent = (color) => {
  if (!color) return "transparent";
  const c = color.trim();
  const cLower = c.toLowerCase();
  if (cLower.startsWith("#")) {
    if (c.length === 7) return c + "00";
    if (c.length === 4) {
      const r = c[1], g = c[2], b = c[3];
      return `#${r}${r}${g}${g}${b}${b}00`;
    }
  } else if (cLower.startsWith("rgb(")) {
    return cLower.replace("rgb(", "rgba(").replace(")", ", 0)");
  }
  return "transparent";
};

const makeColorOpaque = (color, fallback) => {
  if (!color) return fallback;
  const c = color.trim();
  const cLower = c.toLowerCase();
  if (cLower === "transparent") return fallback;
  if (cLower.startsWith("#")) {
    if (c.length === 9 && cLower.endsWith("00")) {
      return c.slice(0, 7);
    }
    if (c.length === 5 && cLower.endsWith("0")) {
      return c.slice(0, 4);
    }
  } else if (cLower.startsWith("rgba(")) {
    const parts = c.split(",");
    if (parts.length === 4) {
      return parts.slice(0, 3).join(",").replace(/rgba\(/i, "rgb(") + ")";
    }
  }
  return fallback;
};

const CSS_COLOR_HELP = "Accepts CSS color values: hex (#rgb, #rrggbb, #rrggbbaa), named colors (red), rgb()/rgba(), hsl()/hsla(), hwb(), lab(), lch(), oklab(), and oklch(). The separate percentage multiplies the color's own alpha.";

const resolveCssColor = color => {
  const source = String(color || "").trim();
  if (!source) return null;
  const shortHex = source.match(/^#([0-9a-f]{3,4})$/i);
  const longHex = source.match(/^#([0-9a-f]{6})([0-9a-f]{2})?$/i);
  if (shortHex || longHex) {
    const hex = (shortHex
      ? shortHex[1].split("").map(channel => channel + channel).join("")
      : `${longHex[1]}${longHex[2] || ""}`).toLowerCase();
    return {
      red: parseInt(hex.slice(0, 2), 16),
      green: parseInt(hex.slice(2, 4), 16),
      blue: parseInt(hex.slice(4, 6), 16),
      alpha: hex.length === 8 ? parseInt(hex.slice(6, 8), 16) / 255 : 1,
    };
  }
  if (typeof document === "undefined") return null;
  const canvas = document.createElement("canvas");
  const context = canvas.getContext("2d");
  if (!context) return null;
  const sentinel = "#010203";
  context.fillStyle = sentinel;
  context.fillStyle = source;
  const resolved = String(context.fillStyle || "");
  if (resolved === sentinel && source.toLowerCase() !== sentinel) return null;
  const match = resolved.match(/^rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)(?:\s*[,/]\s*([\d.]+))?\s*\)$/i);
  if (!match) return resolveCssColor(resolved);
  return {
    red: Math.round(Number(match[1])),
    green: Math.round(Number(match[2])),
    blue: Math.round(Number(match[3])),
    alpha: match[4] === undefined ? 1 : Math.min(1, Math.max(0, Number(match[4]))),
  };
};

const isCssColor = color => Boolean(resolveCssColor(color));

const colorInputHex = (color, fallback = "#000000") => {
  const resolved = resolveCssColor(color);
  if (!resolved) return fallback;
  return `#${[resolved.red, resolved.green, resolved.blue]
    .map(channel => Math.min(255, Math.max(0, channel)).toString(16).padStart(2, "0"))
    .join("")}`;
};

const colorWithOpacity = (color, opacity) => {
  const resolved = resolveCssColor(color);
  if (!resolved) return color;
  const alpha = resolved.alpha * Math.min(100, Math.max(0, Number(opacity))) / 100;
  return `rgba(${resolved.red}, ${resolved.green}, ${resolved.blue}, ${alpha})`;
};

// Excalidraw filters its entire drawing canvas in dark mode. Pre-transform the
// authored canvas color so the visible result still matches the theme swatch.
const canvasColorForExcalidraw = (color, opacity, theme) => {
  const resolved = resolveCssColor(color);
  if (!resolved) return color;
  const alpha = resolved.alpha * Math.min(100, Math.max(0, Number(opacity)));
  if (theme !== "dark") return `rgba(${resolved.red}, ${resolved.green}, ${resolved.blue}, ${alpha / 100})`;
  const desired = [resolved.red, resolved.green, resolved.blue].map(channel => channel / 255);
  const invertAmount = 0.93;
  const invertScale = 1 - 2 * invertAmount;
  const beforeHue = desired.map(channel => (channel - invertAmount) / invertScale);
  const hue180 = [
    [-0.574, 1.43, 0.144],
    [0.426, 0.43, 0.144],
    [0.426, 1.43, -0.856],
  ];
  const source = hue180.map(row => row.reduce((sum, coefficient, index) => sum + coefficient * beforeHue[index], 0));
  const channels = source.map(channel => Math.round(Math.min(1, Math.max(0, channel)) * 255));
  return `rgba(${channels.join(", ")}, ${alpha / 100})`;
};

const DEFAULT_ROLE_THEME = {
  // Authored colour is the normal score appearance. This palette is an
  // explicit role override, useful for score visualisation but never a reason
  // to discard a script's setColor/setColorHue decision.
  enabled: false,
  curveActive: { color: "#c9cdd2", opacity: 100 },
  curveInactive: { color: "#888888", opacity: 35 },
  cursorActive: { color: "#ff3b0a", opacity: 100 },
  cursorInactive: { color: "#888888", opacity: 35 },
  triggerActive: { color: "#00b8e8", opacity: 100 },
  triggerInactive: { color: "#888888", opacity: 35 },
  triggerPulse: { color: "#ff8a3d", opacity: 85 },
};

const normalizeThemeColorToken = (value, fallback) => {
  const source = value && typeof value === "object" ? value : {};
  return {
    color: isCssColor(source.color) ? String(source.color).trim() : fallback.color,
    opacity: Number.isFinite(Number(source.opacity))
      ? Math.min(100, Math.max(0, Number(source.opacity)))
      : fallback.opacity,
  };
};

const normalizeRoleTheme = value => {
  const saved = value && typeof value === "object" ? value : {};
  const next = { ...DEFAULT_ROLE_THEME, ...saved };
  // Migrate the old built-in dark curve swatch. Preserve any other custom
  // role choices; this only repairs the exact legacy default that makes a
  // score effectively disappear against Mono Dark.
  if (saved.enabled === true && String(saved.curveActive?.color || "").toLowerCase() === "#333333" && Number(saved.curveActive?.opacity) === 100) {
    next.curveActive = { ...DEFAULT_ROLE_THEME.curveActive };
  }
  return next;
};

