      const output = outputId ? midiAccessRef.current?.outputs?.get?.(outputId) : null;
      if (output && Number.isInteger(Number(track.program))) {
        output.send([0xc0 | (track.midiChannel - 1), Number(track.program) & 0x7f]);
      }
